```javascript
import {
  PlaneGeometry,
  CircleGeometry,
  EdgesGeometry,
  Mesh,
  LineSegments,
  Group,
  MeshBasicNodeMaterial,
  LineBasicNodeMaterial,
} from 'three/webgpu';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  // Load the card image
  const texture = ctx.textureLoader.load(config.assets.imageUrl);
  // Assume full image is used; no atlas offset needed
  texture.offset.set(0, 0);
  texture.repeat.set(1, 1);

  // Card dimensions (match image aspect 512:320 = 1.6:1)
  const w = 1.6;
  const h = 1.0;
  const planeGeom = new PlaneGeometry(w, h);
  const planeMat = new MeshBasicNodeMaterial({ map: texture, transparent: true });
  const plane = new Mesh(planeGeom, planeMat);

  // Accent edge (line loop)
  const edgeGeom = new EdgesGeometry(planeGeom);
  const edgeMat = new LineBasicNodeMaterial({
    color: config.visual.colors.accent,
    linewidth: 2,
    transparent: true,
    opacity: 0.85,
  });
  const edge = new LineSegments(edgeGeom, edgeMat);

  // Stock badge (small circle in top-right corner)
  const badgeRadius = 0.08;
  const badgeGeom = new CircleGeometry(badgeRadius, 16);
  const badgeMat = new MeshBasicNodeMaterial({ color: '#00ff00' }); // default in‑stock
  const badge = new Mesh(badgeGeom, badgeMat);
  badge.position.set(w / 2 - 0.12, h / 2 - 0.12, 0.01);

  // Root group
  const group = new Group();
  group.add(plane);
  group.add(edge);
  group.add(badge);

  // Apply scene placement
  const sp = config.scenePlacement;
  group.position.copy(sp.position);
  group.rotation.set(sp.rotation[0], sp.rotation[1], sp.rotation[2]);
  group.scale.set(sp.scale[0], sp.scale[1], sp.scale[2]);

  // Stock badge update method (exposed for data binding)
  const stockBadge = {
    update: (inStock) => {
      badgeMat.color.set(inStock ? '#00ff00' : '#ff2a38');
    },
  };

  // GSAP animation references
  let hoverTween = null;
  let pressTween = null;

  // Event handlers
  group.userData.handlers = {
    pointerover: () => {
      if (hoverTween) hoverTween.kill();
      hoverTween = gsap.to(group.position, {
        y: sp.position.y + 0.15,
        duration: 0.3,
        ease: 'power3.out',
      });
    },
    pointerout: () => {
      if (hoverTween) hoverTween.kill();
      gsap.to(group.position, {
        y: sp.position.y,
        duration: 0.3,
        ease: 'power3.out',
      });
    },
    click: () => {
      if (pressTween) pressTween.kill();
      pressTween = gsap.to(group.scale, {
        x: 0.97,
        y: 0.97,
        z: 0.97,
        duration: 0.12,
        ease: 'back.out',
        onComplete: () => {
          gsap.to(group.scale, {
            x: 1,
            y: 1,
            z: 1,
            duration: 0.2,
            ease: 'power2.out',
          });
        },
      });
      // Emit navigation event
      if (typeof config.emit === 'function') {
        config.emit('hub-journal.select', { cardId: config.id || 'journal-card-3' });
      }
    },
  };

  // Expose data binding target
  group.userData.stockBadge = stockBadge;

  // Cleanup resources
  group.userData.cleanup = () => {
    planeGeom.dispose();
    planeMat.dispose();
    edgeGeom.dispose();
    edgeMat.dispose();
    badgeGeom.dispose();
    badgeMat.dispose();
    texture.dispose();
    if (hoverTween) hoverTween.kill();
    if (pressTween) pressTween.kill();
  };

  return group;
}
